\begin{tikzpicture}
\begin{axis}[
    width=0.72\textwidth,
    height=0.46\textwidth,
    xmin=-3.2, xmax=5.2,
    ymin=-0.5, ymax=8,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-2,0,2,4},
    ytick={0,3},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    legend style={at={(0.98,0.98)},anchor=north east,legend columns=1,font=\small}
]
\addplot[thick, domain=-2.5:2.5, samples=80] {x^2};
\addlegendentry{\(f(x)=x^2\)}
\addplot[thick, dashed, domain=-2.5:2.5, samples=80] {x^2+3};
\addlegendentry{\(f(x)+3\)}
\addplot[thick, dotted, domain=-0.5:4.5, samples=80] {(x-2)^2};
\addlegendentry{\(f(x-2)\)}
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.72\textwidth,
    xmin=-2.2, xmax=2.2,
    ymin=-0.5, ymax=4.5,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-2,-1,0,1,2},
    ytick={0,1,4},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-2:2, samples=80] {x^2};
\node[anchor=west] at (axis cs:0.4,3.5) {\(y=x^2\)};
\end{axis}
\end{tikzpicture}

