\begin{tikzpicture}
\begin{axis}[
    width=0.74\textwidth,
    height=0.46\textwidth,
    xmin=-3.5, xmax=4.2,
    ymin=-3.2, ymax=4,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-2,1,3},
    ytick={1.2},
    yticklabels={\(\frac65\)},
